            '<g class="sbot-mouth" opacity="0"><path class="sbot-md" fill="#7a1f1f" stroke="' + INK + '" stroke-width="2.4" stroke-linejoin="round"/>' +
            '<ellipse cx="252" cy="226" rx="15" ry="7" fill="#e5707a" clip-path="url(#' + id + ')"/></g>' +
            '</svg></div></div></div>';
